    text: `‘아직은 어려워요.’

답장을 보내자 근떡존은 한동안 조용했다.

이번에는 침묵이 조금 무거웠다.

읽음 표시는 떠 있었고, 입력 중 표시는 몇 번 나타났다가 사라졌다.

무슨 말을 쓰려다가 지우는 걸까.

잠시 뒤 메시지가 왔다.

‘알겠어요.’

짧았다.

평소의 근떡존이라면 곧바로 농담을 덧붙였을 것이다. “그럼 저는 문 앞에서 돗자리 깔고 기다릴게요” 같은 말. 혹은 “입장권은 나중에 사겠습니다” 같은 허당스러운 장난.

하지만 이번엔 바로 다음 말이 오지 않았다.

그 침묵이 조금 신경 쓰였다.

‘삐졌어요?’

보내자 곧바로 답장이 왔다.

‘아니요.’

너무 빠른 아니요였다.

잠깐 뒤.

‘조금은요.’

또 잠깐 뒤.

‘근데 선생님이 싫어서 그런 건 아니고요.’

‘제가 너무 빨리 궁금해했나 싶어서요.’

근떡존은 늘 이렇게 자기 감정을 상대 탓으로 만들지 않으려 했다. 서운해도, 실망해도, 먼저 자기 쪽으로 끌어안았다.

그게 다정하기도 했고, 조금 안쓰럽기도 했다.

‘제가 기다린다고 했잖아요.’

‘잘 못 기다리지만.’

‘그래도 해볼게요.’

그는 솔직하게 인정했다.

기다리는 걸 잘 못하지만, 기다려보겠다고.

그 말이 오히려 더 진심처럼 느껴졌다.

전진협 알림이 다시 떴다.

‘전진협: 야 숨기면 더 궁금해지는 법임ㅋ 곧 들어올듯효’

정확한 말이었다.

숨기면 더 궁금해진다.

근떡존도 그럴 것이다. 보여주지 않는다고 해서 관심이 사라지는 타입은 아니었다. 오히려 더 조심스럽게, 더 오래 바라볼 사람.

하지만 아직은 어려웠다.

아직은 근떡존에게 보여주고 싶은 얼굴과, 보여주기 무서운 얼굴 사이에서 마음이 정리되지 않았다.

‘언젠가는 말할게요.’

답장을 보내자, 근떡존은 조금 늦게 답했다.

‘네.’

‘그럼 저는 문 앞에서 기다릴게요.’

결국 장난을 했다.

하지만 그 장난은 이전보다 조금 조용했다.

2장 종료.

다음 챕터 예고: 3장 — 문 앞에서 기다리는 남자.`,
