  imagePool: ["/main_ch3_06C.png"],
  background: "/bg_dark_room.png",
  text: `‘가까이 오고 싶어요?’

그 질문을 보내자, 근떡존은 바로 읽었다.

하지만 답은 오지 않았다.

한참 동안.

전진협 방에서는 그 사이에도 헛소리가 올라왔다.

‘근바섭: 근떡존님 조용한데 지금 개인톡중임?’

‘쮋: 백퍼’

‘아로벤: 아 둘만의 공기 개빡치네 진짜.’

‘타조: ㅋㅋ 갠톡으로 이 방 생각보다 너무 더티해서 못있겠다고 런각 재실듯...’

‘유칼립투스나무: 이렇게 또 한명 가시네요...’

그리고 마침내 근떡존의 답장이 왔다.

‘네.’

짧았다.

이번엔 도망가지 않았다.

잠깐 뒤.

‘가까이 가고 싶어요.’

또 잠깐 뒤.

‘처음부터요.’

그 문장을 읽고 손이 멈췄다.

근떡존은 이어서 보냈다.

‘편의점에서 처음 봤을 때부터.’

‘근데 그때는 제가 이런 말 하면 안 된다고 생각했어요.’

‘히든님이 싫어할 수도 있고.’

‘제가 이상하게 보일 수도 있고.’

‘남자가 남자를 좋아하는 거 불편해하는 사람도 많으니까.’

또 잠깐 뒤.

‘그래서 일본어 핑계 대고.’

‘길치 핑계 대고.’

‘장보기 핑계 대고.’

‘그냥 옆에 있고 싶었어요.’

그 문장은 너무 솔직했다.

그리고 너무 오래 숨겨온 마음 같았다.

전진협 방은 잠깐 조용해졌다.

히든이 일부를 옮기지 않았는데도,
왠지 그 순간만큼은 전진협도 눈치채는 것 같았다.

근떡존은 다시 보냈다.

‘오늘 전진협 들어와서.’

‘히든님이 남자 얘기하는 거 보고.’

‘제가 너무 좋아하면 안 되는 사람은 아닐지도 모른다고 생각했어요.’

잠깐 뒤.

‘그 생각이 들어서.’

‘좀 많이 행복했어요.’

또 잠깐 뒤.

‘무섭기도 하고요.’

‘제가 기대했다가 아니면 좀 아플 것 같아서.’

그 말이 조용히 남았다.

근떡존은 드디어 숨기지 않았다.

적어도 완전히는.

‘그래도.’

‘가까이 가고 싶어요.’

마지막 메시지는 더 이상 장난이 아니었다.

전진협 방에서는 뒤늦게 새 메시지가 올라왔다.

‘유칼립투스나무: 근떡존님, 런치지마세요.’

‘타조: 나가기전에 보지주름갯수 알려주고 가세요.’

‘근바섭: 제가 잘못했어요 나가지마세요 씨발 !’

‘아로벤: 나가기전에 가슴한번 만지게 해달라고 아’

‘쮋: 저분 진심이신거같은데...’

‘금수: 순형이를 사랑해 나는.’

방이 이렇게까지 조용하게 다정해지는 건 드문 일이었다.

히든은 근떡존에게 답장을 보냈다.

‘그럼 천천히 와요.’

읽음은 바로 떴다.

답장은 늦었다.

그리고 마침내 도착했다.

‘네.’

잠깐 뒤.

‘천천히 갈게요.’

또 잠깐 뒤.

‘근데 너무 늦지는 않게요.’

3장 종료.

다음 챕터 예고: 4장 — 전진협 정회원 심사와 첫 질투.`,
