  imagePool: ["/main_ch6_03B.png"],
  background: "/bg_jealous_room.png",
  text: `'질투 많은 타입이었네요.'

그 말을 듣고, 근떡존은 바로 대답하지 못했다.

조금 당황한 얼굴로 선생님을 봤다. 평소의 그 장난스럽고 헐겁던 얼굴이 아니었다. 들킨 사람의 얼굴. 자기조차 몰랐던 자기를 들킨 사람의 얼굴이었다.

"저도 몰랐습니다."

"몰랐어요?"

"네."

"사랑을 해본 적이 없으니까요."

담담한 문장이었지만, 어딘가가 살짝 베이는 듯했다.

"누구를 이렇게 좋아해본 게 처음이라서. 제가 원래 이런 사람인지도 몰랐습니다."

그가 손을 내려다봤다.

"전진협에서 선생님이 다른 사람들이랑 편하게 말하는 것도. 답장이 늦으면 다른 사람이랑 있는 건가 생각하는 것도."

잠깐의 침묵.

"그냥 신경이 쓰입니다."

이성적으로는 알고 있었다. 별일 아닌 일이라는 것도. 그런데 마음은 따로 움직였다. 머리로는 옅게 흘려보낼 수 있는 일이, 가슴 안에서는 자꾸 결을 만들었다.

"저 되게 별로죠."

"왜 그렇게 생각해요."

"이러면 안 된다는 거 알면서도. 제가 선생님한테 맞는 사람인지 모르겠고."

잠깐 뒤.

"선생님은 단단한 사람인데, 저는 이렇게 흔들리니까요."

너무 쉽게 나온 말이었다. 아마도 그가 오래전부터 혼자 되풀이해온 말이었을 것이다.

"저."

조심스럽게 입을 열었다.

"손 잡고 싶습니다."

잠깐 뒤.

"근데 손 잡으면, 제가 너무 좋아할 것 같아서 무섭습니다."

자기 마음이 커져가는 속도를, 그는 두려워하고 있었다. 한 번 잡으면 놓을 수 없을 것 같다는 그 예감이, 그를 망설이게 하고 있었다.`,
