  background: "/bg_dark_room.png",
  text: `9장의 갈림길에서 떡존아 들어가, 라는 말을 들은 다음 날.

근떡존은 이상하게 차분한 아침을 맞이했다.

전진협 채팅방을 열지 않았다. 선생님 카톡도 열지 않았다. 그저 침대에 앉아서 손을 가만히 내려다봤다.

어제 선생님이 했던 말이 자꾸 머릿속에 남아 있었다.

알아요.

그 두 글자만으로, 이상하게 무언가 내려앉는 느낌이었다.

근떡존은 결심을 했다.

오늘은 확인하지 않겠다. 오늘은 메시지 먼저 보내지 않겠다. 오늘은 선생님 동선을 따라 걷지 않겠다.

다 알고 있다고 했다. 그 말을 받았으니까, 적어도 며칠은 자제해야 한다.

그게 사람이 할 수 있는 일이라고 생각했다.

그러나 침대에서 일어나는 데 두 시간이 걸렸다.

그동안 휴대폰을 다섯 번 들었다 놨다 했다. 두 번은 카톡 어플을 열었다가 다시 닫았다. 한 번은 전진협 채팅방까지 들어갔다가 스크롤하지 않고 그대로 나왔다.

자제. 자제. 자제.

본인 입속에서 그 단어를 몇 번 굴렸다.

점심 무렵, 결국 휴대폰을 켜고 말았다.

전진협 채팅방의 새 메시지 수가 47개였다.

47.

읽지 않으면 그 47개 안에 무엇이 있는지 모를 것이다.

선생님이 어떤 글을 올렸는지. 어떤 농담을 했는지. 누구에게 답장을 했는지. 누가 선생님에게 무슨 말을 했는지.

47개 안에서 어떤 일이 일어났는지 모르는 채로 하루를 보낸다는 것.

근떡존은 자기가 그게 가능한 사람이 아니라는 걸, 거의 즉시 깨달았다.

손가락이 채팅방을 열었다. 본인의 의지보다 먼저 움직였다.

47개를 다 읽는 데 5분이 걸렸다.

그 안에 별다른 일은 없었다. 평소대로 시끄러웠고, 평소대로 천박했고, 평소대로 선생님은 적당히 받아치다가 적당히 빠지고, 그 외에는 별 내용이 없었다.

그런데도 근떡존은 그 5분 동안 숨이 한 번도 깊게 쉬어지지 않았다는 걸, 채팅방을 다 읽고 나서야 알아차렸다.

자제는 끝났다.

그리고 자제가 끝났다는 것이, 의외로 그를 평온하게 만들었다.

뭔가를 못 하는 척하는 것보다, 못 한다는 걸 인정하는 쪽이 그에겐 더 편했다.

근떡존은 천천히 메시지창을 열었다.

'형, 오늘 시간 되세요?'

쓰고 보니, 형이라는 글자가 거기 있었다.

언제 그게 입력됐는지 본인도 모를 것이다. 자제하려고 했던 마음이 풀린 그 자리에서, 익숙하지 않은 호칭 하나가 손가락보다 먼저 빠져나간 모양이었다.

근떡존은 그 글자를 한참 봤다.

지울까. 지우고 다시 쓸까.

그러나 그 글자를 보면서, 작게 가슴이 뛰는 것을 느꼈다.

지우지 않았다.

전송 버튼을 누른 뒤에야, 자기가 무엇을 보낸 건지 천천히 깨달았다.`,
