  text: `방광 92%.

여기서부터는 — 근떡존도 본 적 없는 영역이었다.

그는 평생 오줌을 잘 참는 사람으로 살아왔다. 학교 다닐 때도, 군대에서도, 회식 자리에서도. 어떤 상황에서도 자기 통제권 안에서 참고 있었다.

그러나 92%는 그가 알던 영역이 아니었다.

이때부터 신체 반응이 — 그가 통제할 수 없는 방향으로 — 일어나기 시작했다.

첫 번째: 식은땀.

이마에 식은땀이 한 줄기 흘렀다. 이어서 두 줄기. 세 줄기. 그의 얼굴 전체가 미끈하게 젖기 시작했다. 평소엔 운동할 때나 흘리던 땀이었다. 지금은 화장실을 못 가서 흘리고 있었다.

두 번째: 몸 떨림.

그의 큰 몸이 작게 떨리기 시작했다. 처음엔 두 다리만. 그 다음엔 허벅지. 그 다음엔 허리. 그러다 결국 어깨까지 살짝 떨렸다. 추워서가 아니었다. 그의 몸 전체가 — 안에서 출구를 찾는 압력에 — 신경계가 과부하 걸려서 — 떨고 있었다.

세 번째: 시야 변화.

평소엔 또렷하던 시야가 — 갑자기 흐려졌다. 안구가 살짝 흔들리는 듯한 느낌. 어딘가 멀리서 사물을 보고 있는 듯한 감각. 그것은 의식이 살짝 후퇴하는 신호였다.

네 번째: 호흡.

호흡이 짧아졌다. 평소엔 느리게 들어쉬고 천천히 내쉬던 그가, 이제는 헉헉대기 시작했다. 들숨 — 짧게. 날숨 — 더 짧게. 산소가 부족한 게 아니라, 의식 전체가 한 점에 집중되어서 다른 시스템들이 다 어긋나고 있었다.

"으아아아아."

근떡존이 처음으로 진짜 비명을 냈다.

신음이 아니었다. 비명이었다. 큰 덩치에서 나오는 — 본인도 못 들어본 — 비명이었다.

선생님이 그제서야 한 번 돌아봤다.

"...떡존?"

『...형!!! 저!!! 화장실!!!』

근떡존이 처음으로 형이라는 호칭을 입에서 꺼냈다.

위급한 상황이라 어쩔 수 없었다.

『가!! 빨리 가!!』

선생님이 회의 화면을 음소거하고 외쳤다.

근떡존이 일어나려 했다.

그런데.

일어나지지 않았다.

다리에 힘이 풀려 있었다.

92%의 방광은 — 인간의 다리 근육의 통제권을 일부 가져간 상태였다.

자기 두 다리에 자기 의지가 닿지 않았다.

『...선생님... 다리가...』

『뭐!?』

『다리가 안 움직여요!!』

선생님이 노트북을 박차고 일어났다.

근떡존에게 달려왔다.

『떡존아!! 정신 차려!!』

근떡존은 자기 사타구니를 두 손으로 꽉 누르고 있었다. 두 다리를 X자로 꼬고, 식은땀을 줄줄 흘리며, 작은 비명을 띄엄띄엄 내고 있었다.

이 큰 덩치의 남자가 — 작은 거실 한가운데서 — 그렇게 무너지고 있었다.

선생님이 그를 들어 올리려 했다.

진짜로 들어 올리려 했다.

『형이!! 데려갈게!!』

『으아아아』

『꽉 잡아!!』

『으아아아아아아!!!』

방광 95%.

선생님이 그를 안아 들었다. 그러나 떡존은 너무 컸다. 190cm짜리 인간을 50kg대 선생님이 들 수 있을 리가 없었다.

선생님이 비틀거렸다.

『떡존아!!』

『으아아아아아아아아아!!!!』

방광 97%.

근떡존의 의식이 흐려지기 시작했다.

방광 99%.`,
