  imagePool: ["/bladder_ch7_01.png"],
  background: "/bg_room_day.png",
  text: `방광 차원에서 돌아온 지 사흘이 지났다.

근떡존은 그 사흘 동안 화장실에 한 번도 가지 않았다.

진짜로 한 번도 안 갔다.

처음에는 본인도 의심했다. 자기가 가서도 모르고 왔거나, 잠결에 다녀왔거나, 아니면 방광 차원에서의 인챈트가 일시적인 것이거나. 그러나 시간이 갈수록 분명해졌다.

그의 방광은 진짜로 진화한 상태였다.

물을 아무리 마셔도 채워지지 않았다. 정확히는, 채워지긴 채워지는데 그 채워지는 속도가 평범한 인간의 것이 아니었다. 2L를 마시면 5%쯤 차올랐다. 4L를 마시면 10%. 그가 사흘 동안 마신 물은 총 18L였다. 그런데 그의 방광은 아직 47%였다.

이것은 인간이 도달할 수 있는 영역이 아니었다.

근떡존은 자기 안에서 일어난 변화를 어디다 어떻게 말해야 할지 몰랐다. 의사한테 가서 "제가 방광 차원에 다녀와서 단군 다음으로 인챈트를 받았는데요"라고 말할 수도 없는 노릇이었다.

그래서 그는 그저 평소처럼 살았다.

다만 한 가지 문제는, 사흘이 넘도록 화장실에 안 가는 사람을 옆에서 매일 보는 사람이 있었다는 것이었다.

선생님이었다.

"근떡존."

오후 카페였다.

"네."

"너 화장실 언제 갔어?"

근떡존은 잠깐 굳었다.

"...글쎄요."

"글쎄가 아니라."

"기억이 잘 안 나네요."

"기억이 안 나?"

"네."

"...."

선생님은 잠시 그를 봤다.

평소엔 사람을 잘 읽는 사람이었다. 그게 직업병이라고 했었다. 그래서 지금도 떡존의 얼굴을 보고 무언가를 읽고 있었다.

"솔직히 말해."

"...."

"화장실 안 간 지 며칠 됐어?"

근떡존은 거짓말을 잘 못하는 사람이었다.

"...사흘이요."

"사흘?"

"네."

"사흘 동안 안 갔다고?"

"네."

"...."

선생님은 한참 동안 떡존을 봤다.

표정이 천천히 변했다.

처음엔 의심. 그 다음엔 걱정. 그 다음엔 — 뭔가 다른 감정이었다. 근떡존은 그것을 정확히 읽지 못했다.

"근떡존."

"네."

"너 의사 가야 되는 거 아니야?"

"아니요. 멀쩡합니다."

"사흘 동안 안 가는 게 멀쩡한 게 아니야."

"근데 진짜 멀쩡합니다."

근떡존은 잠시 망설이다가, 결국 솔직하게 말했다.

"제가 그... 좀 변했어요."

"변해?"

"네. 방광이요."

선생님은 그 말을 듣고 한참 침묵했다.`,
