  imagePool: ["/bladder_ch8_04.png"],
  background: "/bg_un_hall.png",
  text: `사하라 작전이 끝나고, 전 세계 언론이 일제히 K-방광을 다뤘다.

【K-Bladder Saves Australia from Eternal Inferno】 (BBC)
【Le Vessie Coréenne Sauve l'Humanité】 (Le Monde)
【膀胱英雄: 韓國尿道, 拯救地球】 (人民日報)
【방광 한 명이 지구를 구했다】 (조선일보)

CNN에서는 K-방광 다큐멘터리를 제작하기 시작했다.

NHK는 K-방광 특집 방송을 편성했다.

심지어 알자지라에서도 K-방광에 관한 호의적인 기사를 냈다. 사하라 인근 국가들이 식수난 해결의 가능성을 보았다는 내용이었다.

그리고 한 달 뒤, UN에서 공식 초청장이 왔다.

UN 사무총장이 직접 떡존에게 표창을 수여하겠다는 내용이었다.

표창식은 뉴욕 UN 본부에서 진행됐다.

근떡존은 정장을 입었다. 평소엔 입어본 적도 없는 정장이었다. 선생님이 옆에서 넥타이를 매줬다.

『잘 어울리네.』

"감사합니다."

『이 정장 너 사 입혀준 사람이 누군지 잊지 마.』

"네. 선생님이세요."

『그럼 됐어.』

표창식장에는 200개 국가의 외교관들이 모여 있었다. 모두가 떡존을 보고 있었다. 떡존의 방광을 보고 있었다.

UN 사무총장이 떡존을 향해 다가왔다.

「Ladies and gentlemen. Today, we honor a man whose... unique gift has saved millions of lives.」

『His name is...』

『...Kim DDeok-Jon.』

『The K-Bladder.』

전 세계 외교관들이 일제히 박수를 쳤다.

UN 사무총장이 떡존에게 메달을 걸어줬다.

표창식장 객석에서는 선생님이 앉아 있었다. 선생님은 손수건을 꺼내고 있었다.

울고 있었다.

진심으로 울고 있었다.

근떡존은 메달을 건 채로 객석을 봤다. 선생님이 눈물을 닦으며 카메라를 들고 있었다. 이 모든 것을 영상으로 찍고 있었다.

처음 만났을 때를 떠올렸다.

편의점 앞에서 쿠폰 못 쓰던 금발 남자.
일본어한테 두들겨 맞고 있던 사람.
도시락 앞에서 5분 동안 멍때리던 사람.

그가 지금 UN 본부에서 메달을 받고 있었다.

존나 인생이었다.



표창식 후, 근떡존과 선생님은 호텔로 돌아갔다.

호텔 방에서 둘은 야경을 봤다. 뉴욕의 야경이었다. 화려했다.

근떡존이 선생님에게 천천히 입을 열었다.

"선생님."

『응.』

"저 사업 하나 시작해보고 싶어요."

『사업?』

"네."

근떡존은 호텔 방의 화이트보드 앞으로 갔다. 선생님이 호기심에 다가왔다.

근떡존이 화이트보드에 그림을 그리기 시작했다.

방광. 댐. 그리고 그 사이를 잇는 화살표들.

그리고 큰 글씨로.

【방광댐 주식회사】 (Bladder Dam Inc.)

선생님은 그 그림을 한참 봤다.

『떡존아.』

"네."

『이거 진심이야?』

"네. 진심이에요."

『...어떻게 운영할 건데?』

근떡존이 화이트보드에 사업 모델을 그렸다.

물 부족 국가들과 MOU를 체결한다. 정수 시스템을 갖춘 시설을 운영한다. 자기는 정기적으로 출장을 가서 풀 차징과 분사를 진행한다. 그 대가로 식수 공급료를 받는다.

UN과는 ESG 차원에서 협력한다.

K-방광 굿즈 라인은 그대로 유지하면서, 추가로 K-방광 콘서트, K-방광 박물관, K-방광 테마파크까지 확장 가능.

선생님이 화이트보드를 봤다.

오래 봤다.

『...떡존아.』

"네."

『이거.』

"네."

『대박이네.』

근떡존이 작게 웃었다.

『나 투자할게.』

"진짜요?"

『1억. 시드 라운드에 넣을게.』

"...."

『그리고.』

"네."

『내가 CFO 할게.』

근떡존은 그 말을 듣고 잠깐 멈췄다.

CFO.

선생님이 자기 방광 회사의 CFO가 되겠다고 했다.

『뭐야 그 표정.』

"감동받았어요."

『싫어?』

"아니요. 너무 좋아서요."

근떡존이 작게 웃었다.

자기 인생이 어디로 가고 있는지는 모르겠지만, 분명한 건 하나였다.

옆에 선생님이 같이 가고 있었다.

방광 루트 8장 종료.

다음 챕터 예고: 9장 — 나스닥의 방광왕.`,
