  background: "/bg_cafe_day.png",
  text: `한 달이 더 지났다.

형이 묻어두었던 위화감은 — 묻어둔 채로 — 점점 자라고 있었다.

이전엔 며칠에 한 번 떠오르던 위화감이, 이제는 매일 떠올랐다. 떡존이 보내는 메시지 한 줄, 떡존이 잡는 손의 힘, 떡존이 자기를 보는 눈빛 — 그 작은 것들이 매일 한 번씩 형의 안쪽 어딘가를 건드렸다.

전진협 사람들의 말은 여전히 머릿속에 있었다. "집착광공 ㅈㄴ 사랑받는 거." 그 말이 위로처럼 들리던 시절이 있었다.

그러나 한 달이 지난 지금 — 그 말이 더 이상 위로가 되지 않았다.

이건 사랑의 결이 아니다.

형이 어느 순간부터 그렇게 생각하기 시작했다.

오늘 점심이었다. 형이 학교 동료와 카페에서 점심을 먹고 있었다. 그 동료는 형의 친한 후배였다. 평소 형이 자기 속내를 종종 풀어놓던 사람.

『...형 좀 어때.』 후배가 물었다.

『...』

『...요즘 안 좋아 보여.』

형이 잠깐 침묵했다.

그리고 작게 입을 열었다.

『...그 사람 좀 이상해.』

『...어떻게.』

『매일 보고 받아. 내 동선을. 내가 누구랑 있는지.』

『...』

『답장 5분 늦으면 다섯 줄 메시지 와.』

『형이랑 있을 때도 휴대폰 내가 누구한테 답장하는지 흘끔거려.』

『이게 처음엔 사랑이라고 생각했어. 진짜로.』

『근데 점점 — 다른 결인 것 같아.』

후배가 잠깐 형을 봤다.

『...형 그 사람 좀 무섭다.』

『...어.』

『그게 사랑인지는 모르겠어.』

형이 천천히 끄덕였다.

그리고 작게 — 거의 자기 자신에게 — 한 마디를 던졌다.

『...도망갈까.』

도망갈까.

그 한 마디가 — 카페 안에서 — 작은 진동처럼 흘렀다.

형은 그 한 마디를 던지고 — 자기 자신이 그 단어를 입에서 꺼냈다는 것에 — 잠깐 놀랐다.

자기가 — 떡존에게서 — 도망가는 일을 — 진지하게 생각하고 있다는 것.

그게 자기 안쪽에 진짜로 자리 잡고 있었던 거였다.

전진협 사람들 말은 틀렸다. 이건 사랑이 받기에 너무 격한 게 아니었다. 이건 — 사랑이 아니었다.

다른 무엇이었다.

형이 잠깐 시선을 카페 창밖으로 돌렸다.

그리고 — 그 순간 — 카페 창밖에서 한 사람이 — 그를 보고 있었다.

근떡존이었다.

평소처럼 옷차림이었다. 평소처럼 큰 덩치였다. 평소처럼 — 어딘가 — 다정해 보이는 얼굴이었다.

그런데 그 다정해 보이는 얼굴 안에서 — 형이 — 평소엔 보지 못하던 — 다른 결의 무언가를 봤다.

떡존이 — 들었다.

도망갈까, 라는 그 한 마디를.

카페 창문 너머에서.

들었다는 게 분명했다. 그의 눈이 — 평소의 다정한 눈이 아니었다. 평소의 어리광 부리던 눈이 아니었다. 평소의 헤헤 거리던 눈이 아니었다.

지금 그의 눈은 — 무언가가 영원히 부서진 사람의 눈이었다.

형이 잠깐 굳었다.

후배도 형의 시선을 따라 창밖을 봤다.

『...누구야.』

『...』

『...형 저 사람이 그 사람이야?』

『...어.』

『...형. 일어나자. 우리 다른 데로 가자.』

후배가 형을 일으켰다.

그러나 카페 창밖의 떡존은 — 이미 — 천천히 자리를 떴다.

뒤도 안 돌아보고. 평소처럼.

그러나 — 그가 떠나는 그 뒷모습 안에서 — 형은 — 분명히 — 무언가가 한 번에 — 지금까지와는 다른 방향으로 — 흘러가기 시작했다는 것을 — 알았다.

위험했다.

도망갈까, 라는 그 한 마디가 — 이제 — 형 한 사람의 마음 안에 묻혀 있을 단어가 아니었다.

이 단어를 — 떡존도 — 알게 되었다.`,
